/**
 * @name ash-dynamic
 * @description ash dotfiles — dynamic Catppuccin *glass* theme for Vencord. Follows current-theme.json + ash_dusk ('ash:variant-change').
 * @author ash
 * @version 5.0
 */

:root {
  --ash-rosewater: #f5e0dc;
  --ash-flamingo: #f2cdcd;
  --ash-pink: #f5c2e7;
  --ash-mauve: #cba6f7;
  --ash-red: #f38ba8;
  --ash-maroon: #eba0ac;
  --ash-peach: #fab387;
  --ash-yellow: #f9e2af;
  --ash-green: #a6e3a1;
  --ash-teal: #94e2d5;
  --ash-sky: #89dceb;
  --ash-sapphire: #74c7ec;
  --ash-blue: #89b4fa;
  --ash-lavender: #b4befe;
  --ash-text: #cdd6f4;
  --ash-subtext1: #bac2de;
  --ash-subtext0: #a6adc8;
  --ash-overlay2: #9399b2;
  --ash-overlay1: #7f849c;
  --ash-overlay0: #6c7086;
  --ash-surface2: #585b70;
  --ash-surface1: #45475a;
  --ash-surface0: #313244;
  --ash-base: #1e1e2e;
  --ash-mantle: #181825;
  --ash-crust: #11111b;

  --ash-accent1: var(--ash-mauve);
  --ash-accent2: var(--ash-sky);
  --ash-accent1-rgb: 203, 166, 247;
  --ash-accent2-rgb: 137, 220, 235;

  --ash-glass-bg: color-mix(in srgb, var(--ash-base) 55%, transparent);
  --ash-glass-bg2: color-mix(in srgb, var(--ash-surface0) 50%, transparent);
  --ash-glass-hover: color-mix(in srgb, var(--ash-surface0) 70%, transparent);
  --ash-glass-active: color-mix(in srgb, var(--ash-surface1) 70%, transparent);
  --ash-glass-border: color-mix(in srgb, var(--ash-text) 12%, transparent);
  --ash-border-subtle: color-mix(in srgb, var(--ash-text) 8%, transparent);

  --ash-blur-lg: blur(24px) saturate(160%);
  --ash-blur-xl: blur(36px) saturate(180%);
  --ash-shadow-sm: 0 1px 2px color-mix(in srgb, var(--ash-crust) 30%, transparent);
  --ash-shadow-md: 0 4px 16px color-mix(in srgb, var(--ash-crust) 40%, transparent);
  --ash-shadow-lg: 0 8px 32px color-mix(in srgb, var(--ash-crust) 55%, transparent), 0 0 48px color-mix(in srgb, var(--ash-accent1) 14%, transparent);
  --ash-shadow-accent: 0 4px 24px color-mix(in srgb, var(--ash-accent1) 30%, transparent);

  --background-primary: var(--ash-base);
  --background-secondary: var(--ash-mantle);
  --background-secondary-alt: var(--ash-crust);
  --background-tertiary: var(--ash-crust);
  --background-floating: color-mix(in srgb, var(--ash-base) 82%, transparent);
  --background-modifier-hover: color-mix(in srgb, var(--ash-surface0) 70%, transparent);
  --background-modifier-active: color-mix(in srgb, var(--ash-surface1) 70%, transparent);
  --background-modifier-selected: color-mix(in srgb, var(--ash-surface1) 80%, transparent);
  --background-message-hover: color-mix(in srgb, var(--ash-surface0) 40%, transparent);
  --channeltextarea-background: color-mix(in srgb, var(--ash-surface0) 60%, transparent);

  --text-normal: var(--ash-text);
  --text-muted: var(--ash-subtext0);
  --text-link: var(--ash-sky);
  --text-positive: var(--ash-green);
  --text-warning: var(--ash-yellow);
  --text-danger: var(--ash-red);
  --text-brand: var(--ash-mauve);
  --header-primary: var(--ash-text);
  --header-secondary: var(--ash-subtext0);
  --interactive-normal: var(--ash-subtext1);
  --interactive-hover: var(--ash-text);
  --interactive-active: var(--ash-text);
  --interactive-muted: var(--ash-overlay2);

  --brand-experiment: var(--ash-mauve);
  --brand-experiment-500: var(--ash-mauve);
  --brand-experiment-560: var(--ash-mauve);
  --brand-experiment-600: var(--ash-mauve);
  --brand-spotify: var(--ash-green);

  --green-360: var(--ash-green);
  --yellow-300: var(--ash-yellow);
  --red-400: var(--ash-red);
  --blue-345: var(--ash-blue);

  --input-background: color-mix(in srgb, var(--ash-surface0) 50%, transparent);
  --input-background-active: color-mix(in srgb, var(--ash-surface0) 75%, transparent);
  --scrollbar-thin-thumb: var(--ash-surface1);
  --scrollbar-auto-thumb: var(--ash-surface1);
  --scrollbar-auto-thumb-hover: var(--ash-surface2);
  --scrollbar-auto-scrollbar-color-track: var(--ash-surface0);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-round: 999px;
}

.theme-dark,
.theme-dark[data-theme="dark"] {
  background: var(--ash-base) !important;
}

.theme-dark .app {
  background:
    radial-gradient(120% 80% at 85% -10%, color-mix(in srgb, var(--ash-accent1) 14%, transparent) 0%, transparent 55%),
    radial-gradient(120% 80% at -10% 110%, color-mix(in srgb, var(--ash-accent2) 12%, transparent) 0%, transparent 50%),
    var(--ash-base) !important;
}

.theme-dark .guilds__2b93a {
  background: color-mix(in srgb, var(--ash-base) 40%, transparent);
  backdrop-filter: var(--ash-blur-lg);
}

.theme-dark .channels__6d715 {
  background: color-mix(in srgb, var(--ash-base) 35%, transparent);
  backdrop-filter: var(--ash-blur-lg);
  border-right: 1px solid var(--ash-glass-border);
}

.theme-dark .chat__229b3 {
  background: color-mix(in srgb, var(--ash-base) 40%, transparent);
  backdrop-filter: var(--ash-blur-xl);
}

.theme-dark .messageListItem__037ae:hover,
.theme-dark .message__9d69e:hover {
  background: var(--background-modifier-hover) !important;
  border-radius: var(--radius-md);
}

.theme-dark .scrollableContainer__1d4fb {
  background: color-mix(in srgb, var(--ash-surface0) 55%, transparent);
  border: 1px solid var(--ash-glass-border);
  border-radius: var(--radius-lg);
  backdrop-filter: var(--ash-blur-lg);
}

.theme-dark .menu__1ca1c,
.theme-dark .menu-2n_dvd {
  background: color-mix(in srgb, var(--ash-mantle) 65%, transparent) !important;
  backdrop-filter: var(--ash-blur-xl);
  border: 1px solid var(--ash-glass-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--ash-shadow-lg);
}

.theme-dark .menu_item:hover {
  background: color-mix(in srgb, var(--ash-surface0) 90%, transparent);
  border-radius: var(--radius-md);
}

.theme-dark .lookFilled__e5f77 {
  background: color-mix(in srgb, var(--ash-accent1) 16%, transparent) !important;
  color: var(--ash-text) !important;
  border: 1px solid var(--ash-glass-border);
  transition: all 0.2s ease;
}

.theme-dark .lookFilled__e5f77:hover {
  background: color-mix(in srgb, var(--ash-accent1) 30%, transparent) !important;
  box-shadow: var(--ash-shadow-accent);
  transform: translateY(-1px);
}

.theme-dark .container__36e99 {
  background: color-mix(in srgb, var(--ash-base) 45%, transparent);
  backdrop-filter: var(--ash-blur-lg);
  border-bottom: 1px solid var(--ash-glass-border);
}

.theme-dark .members__573d4 {
  background: transparent;
}

.theme-dark .panels__2e2f4 {
  background: color-mix(in srgb, var(--ash-base) 40%, transparent);
  backdrop-filter: var(--ash-blur-lg);
}

::-webkit-scrollbar-thumb {
  background: var(--ash-surface1) !important;
  border-radius: var(--radius-round) !important;
  border: 2px solid transparent !important;
  background-clip: padding-box !important;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--ash-surface2) !important;
}

::-webkit-scrollbar-track,
::-webkit-scrollbar-corner {
  background: transparent !important;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

@keyframes ashFadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

.theme-dark .modal__9d9e,
.theme-dark .userPopout__8b2b {
  animation: ashFadeIn 0.25s ease;
}

.theme-dark .nitroUpsell_customize {
  display: none !important;
}
